<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import colegioLogo from '../logo/The_Colegio_de_Montalban_Seal (1).png'
import { submitGradeSheet } from '../services/dataService'
const emit = defineEmits(['signout'])
const isMobile = ref(window.innerWidth <= 768); const sidebarCollapsed = ref(false); const view = ref('lists'); const tab = ref('lists'); const searchStudent = ref(''); const selectedSection = ref('all'); const selectedYear = ref('1st Year'); const expandedInstitute = ref(''); const messageAssessment = ref('Midterm'); const activePeriod = ref('midterm'); const showFinalsNotice = ref(false); const submissionSent = ref(false); const replyText = ref(''); const years = ['1st Year', '2nd Year', '3rd Year', '4th Year']; const gradeHeaders = ['Q1', 'Q2', 'Q3', 'Q4', 'Q5', 'A1', 'A2', 'A3', 'A4', 'R1', 'Mid Ex']; const midtermItems = [{ name: 'Quiz' }, { name: 'Activity' }, { name: 'Recitation' }, { name: 'Major Exam' }]
const institutes = [{ id: 'ibe', name: 'IBE - Institute of Business Entrepreneurship', groups: [{ name: 'BUSINESS LAW', courses: [{ code: 'BUSLAW1', section: 'BSBA - 1A', students: 30, name: 'Business Law' }, { code: 'BUSLAW1', section: 'BSBA - 1B', students: 30, name: 'Business Law' }, { code: 'BUSLAW1', section: 'BSBA - 1C', students: 30, name: 'Business Law' }, { code: 'BUSLAW1', section: 'BSBA - 1D', students: 30, name: 'Business Law' }] }, { name: 'FINANCIAL ACCOUNTING', courses: [{ code: 'FINACC', section: 'BSBA - 1A', students: 30, name: 'Financial Accounting' }, { code: 'FINACC', section: 'BSBA - 1B', students: 30, name: 'Financial Accounting' }, { code: 'FINACC', section: 'BSBA - 1C', students: 30, name: 'Financial Accounting' }, { code: 'FINACC', section: 'BSBA - 1D', students: 30, name: 'Financial Accounting' }] }] }, { id: 'ics', name: 'ICS - Institute of Computing Studies', groups: [{ name: 'COMPUTING FUNDAMENTALS', courses: [{ code: 'ITFUND1', section: 'BSIT - 1A', students: 32, name: 'Computing Fundamentals' }, { code: 'ITFUND1', section: 'BSIT - 1B', students: 30, name: 'Computing Fundamentals' }] }] }, { id: 'ioe', name: 'ITE - Institute of Teachers Education', groups: [{ name: 'FOUNDATIONS OF EDUCATION', courses: [{ code: 'EDU101', section: 'BEED - 1A', students: 28, name: 'Foundations of Education' }] }] }]
const selectedInstitute = computed(() => institutes.find(institute => institute.id === expandedInstitute.value) || institutes[0]); const visibleGroups = computed(() => selectedInstitute.value.groups.map(group => ({ ...group, courses: group.courses.filter(course => selectedSection.value === 'all' || course.section.includes(selectedSection.value)) }))); const sections = computed(() => institutes.flatMap(institute => institute.groups.flatMap(group => group.courses.map(course => course.section)))); const messages = reactive([{ id: '23-00001', name: 'Barcial, Trishia Mae Trance', section: 'BSIT - 4A', preview: 'Hi po maam, may problema po ata ako sa grades. Mataas naman po yung midterm ko.', course: { name: 'Business Law', section: 'BSBA - 1A' } }]); const activeMessage = ref(messages[0]); const selectedCourse = ref({ name: 'Business Law', section: 'BSBA - 1A' }); const gradeStudents = reactive([{ id: '23-00000', name: 'Dela Cruz, Antonio Pakpak', midterm: '', scores: {} }, { id: '23-00001', name: 'Barcial, Trishia Mae Trance', midterm: '', scores: {} }, { id: '23-00002', name: 'Mercancil, Angel Mae Ramos', midterm: '', scores: {} }, { id: '23-00003', name: 'Ortega, Marvhenne Klein Butt', midterm: '', scores: {} }, { id: '23-00004', name: 'Sardillo, Vhyancxa Fauline Tablon', midterm: '', scores: {} }, { id: '23-00005', name: 'Enage, Daryllykett Tumbagahan', midterm: '', scores: {} }, { id: '23-00006', name: 'Jallorina, Xyrene Carmelyn Ancheta', midterm: '', scores: {} }]); const filteredMessages = computed(() => messages.filter(message => `${message.name} ${message.id}`.toLowerCase().includes(searchStudent.value.toLowerCase())))
function toggleInstitute(id) { expandedInstitute.value = expandedInstitute.value === id ? '' : id }; function openGrades(course) { selectedCourse.value = course || selectedCourse.value; activePeriod.value = 'midterm'; view.value = 'grades' }; function openFinals() { const today = new Date(); const finalsDate = new Date('2026-10-10T00:00:00'); if (today < finalsDate) { showFinalsNotice.value = true; return }; activePeriod.value = 'finals' }; function submitToRegistrar() { submitGradeSheet({ code: `${selectedCourse.value.section}-BUSLAW1`, subject: selectedCourse.value.name, section: selectedCourse.value.section, professor: 'Professor', semester: '1st Sem, A.Y. 2025-26', students: gradeStudents.length, submitted: new Date().toLocaleDateString('en-US'), status: 'Submitted' }); submissionSent.value = true; emit('submitted') }; function syncFinalAction() { const button = document.querySelector('.add-button'); if (!button) return; const tableCard = document.querySelector('.grade-table-card'); const finalView = activePeriod.value === 'finals' || activePeriod.value === 'final-grade'; if (tableCard && button.parentElement !== tableCard) tableCard.appendChild(button); button.className = 'submit-bottom'; button.textContent = submissionSent.value ? '✈ Submitted to Registrar' : '✈ Submit to Registrar'; button.onclick = submitToRegistrar; const actions = document.querySelector('.grade-actions'); if (actions) actions.querySelectorAll('button:not(.add-button)').forEach(item => { item.style.display = finalView ? 'none' : '' }); if (tableCard && finalView && !tableCard.querySelector('.save-draft')) { const draft = document.createElement('button'); draft.className = 'save-draft'; draft.type = 'button'; draft.textContent = '▣ Save Draft'; tableCard.insertBefore(draft, button) } }; watch([activePeriod, submissionSent], syncFinalAction); function openMessages() { tab.value = 'messages'; view.value = 'messages' }; function goToLists() { view.value = 'lists'; tab.value = 'lists' }; function signOut() { emit('signout') }; function handleResize() { isMobile.value = window.innerWidth <= 768 }; onMounted(() => { window.addEventListener('resize', handleResize); syncFinalAction() }); onUnmounted(() => window.removeEventListener('resize', handleResize))
</script>

